from src.nodes.base import BaseNode
from src.runtime.assets.semantic import get_asset_knowledge_graph

class Hou_Mcp_Asset_Graph(BaseNode):
    name = "hou_mcp_asset_graph"

    def __init__(self):
        super().__init__()
        # [AUTO-GENERATED-PORTS-START]
        self.add_input("action",      "string", widget_type="text", default="query")
        self.add_input("asset_id",    "string", widget_type="text")
        self.add_input("target_id",   "string", widget_type="text")
        self.add_input("relation",    "string", widget_type="text")
        self.add_input("weight",      "float",  widget_type="float", default=1.0)
        self.add_input("assets_list", "list")
        self.add_output("relationships", "list")
        self.add_output("neighbors",     "list")
        self.add_output("stats",         "any")
        self.add_output("ok",            "bool")
        # [AUTO-GENERATED-PORTS-END]

    async def execute(self, inputs):
        action     = str(inputs.get("action") or "query").strip().lower()
        asset_id   = str(inputs.get("asset_id") or "").strip()
        target_id  = str(inputs.get("target_id") or "").strip()
        relation   = str(inputs.get("relation") or "").strip()
        weight     = float(inputs.get("weight") or 1.0)
        assets_list= inputs.get("assets_list") or []
        try:
            graph = get_asset_knowledge_graph()
            if action == "add":
                rel = graph.add_relationship(asset_id, relation, target_id, weight=weight)
                return {"relationships": [rel.to_dict()], "neighbors": [], "stats": {}, "ok": bool(rel.source_id), "exec_out": True}
            elif action == "remove":
                ok = graph.remove_relationship(asset_id, relation, target_id)
                return {"relationships": [], "neighbors": [], "stats": {}, "ok": ok, "exec_out": True}
            elif action == "query":
                rels = graph.query_relationships(asset_id, relation_type=relation or None)
                return {"relationships": [r.to_dict() for r in rels], "neighbors": [], "stats": {}, "ok": True, "exec_out": True}
            elif action == "neighbors":
                neighbors = graph.get_neighbors(asset_id, relation_type=relation or None)
                return {"relationships": [], "neighbors": neighbors, "stats": {}, "ok": True, "exec_out": True}
            elif action == "build":
                added = graph.build_graph(assets_list if isinstance(assets_list, list) else [])
                return {"relationships": [], "neighbors": [], "stats": {"added": added}, "ok": True, "exec_out": True}
            elif action == "stats":
                stats = graph.get_statistics()
                return {"relationships": [], "neighbors": [], "stats": stats, "ok": True, "exec_out": True}
            elif action == "clear":
                graph.clear()
                return {"relationships": [], "neighbors": [], "stats": {}, "ok": True, "exec_out": True}
            else:
                return {"relationships": [], "neighbors": [], "stats": {}, "ok": False, "exec_out": True}
        except Exception as e:
            self.log_error(f"hou_mcp_asset_graph failed: {e}")
            return {"relationships": [], "neighbors": [], "stats": {}, "ok": False, "exec_out": True}

def register_node():
    return Hou_Mcp_Asset_Graph
